def compute(vars):
    gross_profit = vars["v1"]
    net_sales = vars["v2"]

    if net_sales == 0:
        return None

    gross_margin_percent = (gross_profit / net_sales) * 100

    return {
        "value": gross_margin_percent,
        "trace": {
            "gross_profit": gross_profit,
            "net_sales": net_sales,
            "gross_margin_percent": gross_margin_percent,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
